extension CalimeroClient {
    /// The `packages` routes of the node API, one method per operation.
    public nonisolated var packagesApi: Packages { Packages(client: self) }

    /// The `packages` routes of the node API (``CalimeroClient/packagesApi``).
    public struct Packages: Sendable {
        let client: CalimeroClient

        /// Upload a raw component: `POST /bundles` (`bundle_put`).
        ///
        /// A `calimero:app` component, 16 MiB at most; only on a node started with `--allow-unsigned-bundles` or `--dev`. A WASM core module (SDK 0.12) is refused `400 UNSUPPORTED_BUNDLE`.
        ///
        /// **Who:** an installer (an account holder, or an unscoped API key that is not read-only).
        @discardableResult
        public func bundlePut(body: Data) async throws -> Operations.BundlePut.Output.Ok.Body.JsonPayload {
            let input = Operations.BundlePut.Input(body: .applicationWasm(HTTPBody(body)))
            return try await client.perform { api in
                try await api.bundlePut(input).ok.body.json
            }
        }

        /// Register a frontend origin: `POST /package-origins/{package}` (`origins_add`).
        ///
        /// By whoever manages the package, with a passkey step-up over the change.
