            return try await client.perform(passkey: passkey) { api in
                try await api.originsRemove(input).ok.body.json
            }
        }

        /// One package: `GET /packages/{package}` (`package_get`).
        ///
        /// The versions the caller may see; `404` when none.
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func get(package: Swift.String) async throws -> Components.Schemas.Package {
            let input = Operations.PackageGet.Input(path: .init(package: package))
            return try await client.perform { api in
                try await api.packageGet(input).ok.body.json
            }
        }

        /// Install a release from the registry: `POST /packages/install` (`package_install`).
        ///
        /// **Who:** an installer (an account holder, or an unscoped API key that is not read-only).
        @discardableResult
        public func install(package: Swift.String, version: Swift.String) async throws -> Operations.PackageInstall.Output.Ok.Body.JsonPayload {
            let input = Operations.PackageInstall.Input(body: .json(.init(package: package, version: version)))
            return try await client.perform { api in
                try await api.packageInstall(input).ok.body.json
            }
        }

        /// Installed packages: `GET /packages` (`package_list`).
        ///
        /// Only the releases the caller may see.
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func list() async throws -> Operations.PackageList.Output.Ok.Body.JsonPayload {
            let input = Operations.PackageList.Input()
            return try await client.perform { api in
                try await api.packageList(input).ok.body.json
            }
        }

        /// Uninstall a package: `DELETE /packages/{package}` (`package_uninstall`).
        ///
        /// Every version; refused while an app runs one.
        ///
        /// **Who:** an account holder (a passkey session not bound to an app's frontend).
        @discardableResult
        public func uninstall(package: Swift.String) async throws -> Components.Schemas.Written {
            let input = Operations.PackageUninstall.Input(path: .init(package: package))
            return try await client.perform { api in
                try await api.packageUninstall(input).ok.body.json
            }
        }

        /// Upload a signed release: `POST /packages` (`package_upload`).
        ///
        /// A signed `.mpk`, checked as an install from the registry is (signature, artifact digests, `minRuntimeVersion`, the package's pinned signer, every service compiles). Only with `--dev`; otherwise `403 UPLOADS_DISABLED`.
        ///
        /// **Who:** an installer (an account holder, or an unscoped API key that is not read-only).
        @discardableResult
        public func upload(body: Data) async throws -> Operations.PackageUpload.Output.Ok.Body.JsonPayload {
            let input = Operations.PackageUpload.Input(body: .binary(HTTPBody(body)))
            return try await client.perform { api in
                try await api.packageUpload(input).ok.body.json
            }
        }

        /// Uninstall one version: `DELETE /packages/{package}/{version}` (`package_version_uninstall`).
